mapper.select:
SELECT spu_id, spec_text FROM ( SELECT ssv.spu_id AS spu_id, string_agg(gsv.name, '×' ORDER BY ssv.sort ASC) AS spec_text, row_number() OVER ( PARTITION BY ssv.spu_id ORDER BY sk.sales_price ASC NULLS LAST, ssv.sku_id ASC ) AS rn FROM goods_sku_spec_value ssv INNER JOIN goods_sku sk ON sk.id = ssv.sku_id AND sk.del_flag = '0' LEFT JOIN goods_spec_value gsv ON gsv.id = ssv.spec_value_id WHERE ssv.spu_id IN
#{id}
GROUP BY ssv.spu_id, ssv.sku_id, sk.sales_price ) t WHERE t.rn = 1
